codeExamples.code:
from confluent_kafka import Consumer, TopicPartition, KafkaError, KafkaException
from confluent_kafka import OFFSET_BEGINNING

consumer = Consumer({
    "bootstrap.servers": "localhost:9092",
    "group.id": "orders-svc",
    "enable.auto.commit": False,          # we commit manually after processing
    "auto.offset.reset": "earliest",      # only used if no committed offset exists
})

# On assignment, optionally seek partition 0 back to the beginning to replay it
def on_assign(c, partitions):
    for tp in partitions:
        if tp.partition == 0:
            tp.offset = OFFSET_BEGINNING   # replay this partition from offset 0
    c.assign(partitions)                   # apply the (possibly seeked) assignment

consumer.subscribe(["orders"], on_assign=on_assign)

try:
    while True:
        msg = consumer.poll(timeout=1.0)
        if msg is None:
            continue
        if msg.error():
            if msg.error().code() == KafkaError._PARTITION_EOF:
                continue
            raise KafkaException(msg.error())
        # ---- process the record ----
        print(f"p{msg.partition()} @ {msg.offset()}: {msg.value().decode()}")
        # commit the NEXT offset after successful processing => at-least-once
        consumer.commit(message=msg, asynchronous=False)
except KeyboardInterrupt:
    pass
finally:
    consumer.commit(asynchronous=False)    # final sync commit of last position
    consumer.close()

